/**
 * The export draws the box and the tick as one filled compound path. The tick
 * half is the *outline* of a stroke — every point on it sits 1.0 units from the
 * centreline below — so it is split back out into a real stroke here. Renders
 * identically, and unlike a fill it can be drawn progressively.
 */
export const CHECK_TICK_PATH = "M11 17 14 20 21 13";
export const CHECK_TICK_WIDTH = 2;

const CHECKBOX_BOX_PATH =
  "M28 6V26C28 26.5304 27.7893 27.0391 27.4142 27.4142C27.0391 27.7893 26.5304 28 26 28H6C5.46957 28 4.96086 27.7893 4.58579 27.4142C4.21071 27.0391 4 26.5304 4 26V6C4 5.46957 4.21071 4.96086 4.58579 4.58579C4.96086 4.21071 5.46957 4 6 4H26C26.5304 4 27.0391 4.21071 27.4142 4.58579C27.7893 4.96086 28 5.46957 28 6ZM26 26V6H6V26H26Z";

/** Loading mark for the "Verifying..." status row. */
export function SpinnerIcon({
  size = 32,
  className,
}: {
  size?: number;
  className?: string;
}) {
  return (
    <svg
      className={className}
      width={size}
      height={size}
      viewBox="0 0 32 32"
      fill="none"
      aria-hidden="true"
      focusable="false"
    >
      <path d={LOADING_PATH} fill="currentColor" />
    </svg>
  );
}

/** Checkbox mark for the "Authenticated" status row. */
export function CheckSquareIcon({
  size = 32,
  className,
  tick,
}: {
  size?: number;
  className?: string;
  /** Replaces the static tick, so the caller can animate it. */
  tick?: React.ReactNode;
}) {
  return (
    <svg
      className={className}
      width={size}
      height={size}
      viewBox="0 0 32 32"
      fill="none"
      aria-hidden="true"
      focusable="false"
    >
      <path d={CHECKBOX_BOX_PATH} fill="currentColor" />
      {tick ?? (
        <path
          d={CHECK_TICK_PATH}
          stroke="currentColor"
          strokeWidth={CHECK_TICK_WIDTH}
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      )}
    </svg>
  );
}
